export const leafParts=[{id:'epidermis',name:'Epidermis',role:'protect',detail:'Protective, usually transparent surface lets light reach mesophyll.'},{id:'palisade',name:'Palisade mesophyll',role:'light',detail:'Many chloroplasts absorb light near the upper surface.'},{id:'spongy',name:'Spongy mesophyll',role:'gas',detail:'Air spaces allow gases to move between cells.'},{id:'xylem',name:'Xylem',role:'water',detail:'Supplies water and mineral ions to the leaf.'},{id:'phloem',name:'Phloem',role:'sugar',detail:'Transports dissolved sugars for use or storage.'},{id:'guard',name:'Guard cells',role:'pore',detail:'The pair controls the stomatal pore for gas exchange and water loss.'}];
export const leafLabels=['epidermis','palisade','spongy','xylem','guard'];
export const waterSequence=['evaporate','diffuse','pull'];
export const environmentalTrials=[{id:'temperature',name:'Temperature',change:'20 → 30°C',answer:'faster',why:'Faster evaporation and diffusion within this moderate, well-watered comparison.'},{id:'humidity',name:'Humidity',change:'50 → 80% relative humidity',answer:'slower',why:'A smaller water-vapour gradient reduces loss.'},{id:'wind',name:'Air movement',change:'Still air → moving air',answer:'faster',why:'Moving air removes humid air near the leaf.'},{id:'light',name:'Light intensity',change:'Dim → brighter',answer:'faster',why:'More open stomata commonly increase gas exchange and water loss.'}];
export const stomaCounts={upper:[2,1,3],lower:[12,10,14]};
export const temperatureData=[[20,2],[25,3],[30,4]];
export function mean(values){return values.length?values.reduce((a,b)=>a+Number(b),0)/values.length:null;}
export function density(count,area){return Number(area)>0?Number(count)/Number(area):null;}
export function uptake(distance,time,radius=.5){if(distance<0||time<=0||radius<=0)return null;const area=3.14*radius**2;return {distanceRate:distance/time,area,volume:area*distance,volumeRate:area*distance/time};}
export function rootMovement(kind='water',condition='dilute',energy=true){if(kind==='water')return {direction:condition==='dilute'?'in':'out',process:'osmosis',active:false};return {direction:energy?'in':'stopped',process:'active transport',active:true};}
export const sugarDestinations=[{id:'root',name:'Growing root',direction:'down',use:'respire'},{id:'shoot',name:'Growing shoot tip',direction:'up',use:'build'},{id:'store',name:'Storage organ',direction:'down',use:'store'}];
